examples:
//! `///` documents a declaration; optional fields are `T?`.
workflow file_finding
  input title: String
  outcome done: type Finding, route success

/// One reviewer finding.
type Finding {
  title: String,
  /// Absent until a reviewer writes one.
  note: String?,
}

step file
  route done(title: title)

//! An inline schema door names a JSON shape as an AWL type.
workflow ingest_payload
  input raw: Payload
  outcome done: type Payload, route success

type Payload = schema {
  "type": "object",
  "required": ["value"],
  "properties": { "value": { "type": "string" } }
}

step accept
  route done(raw)

//! A worker DOCUMENT: the implementation of one task queue.
worker greeter
  action greet(name: String) -> Greeting
    run json "greeter-tool --json --name $name"

type Greeting { message: String }

//! In a worker document every action carries the command that runs it.
worker archiver
  action archive(path: String) -> Archived
    run "tar -cf archive.tar $path"

type Archived { exit_code: Int, stderr: String }

//! Proofs chain: the first makes the record real, the second its field.
workflow read_deep_note
  input report: Report
  outcome done: type String, route success

type Detail { note: String? }
type Report { title: String, detail: Detail? }

step read
  outcome noted: when report.detail is present and report.detail.note is present,
    route done(report.detail.note)
  outcome bare: otherwise, route done(report.title)

//! On the false edge of `is absent`, the right side reads the value safely.
workflow honor_waiver
  input request: Request
  outcome done: type String, route success

type Waiver  { approved: Bool }
type Request { title: String, waiver: Waiver? }

step judge
  outcome waved: when request.waiver is absent or request.waiver.approved,
    route done("proceed: " + request.title)
  outcome held: otherwise, route done("held: " + request.title)

//! `run json` names the capture selector: stdout parses into the type.
worker probes
  action host_report(host: String) -> Report
    run json "host-tool --json --host $host"

type Report { cpu_count: Int, host: String }

//! `run json` parses the command's stdout into the declared type.
worker probes
  action disk_report(mount: String) -> Report
    run json "disk-tool --json $mount"

type Report { free_bytes: Int, mount: String }
